package com.aiintelligence.quality;

import com.aiintelligence.common.NotFoundException;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class QualityRepository {
    private final JdbcTemplate jdbc;public QualityRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
    public void saveFeedback(long eventId,EventFeedbackRequest r){int n=jdbc.update("UPDATE ai_event_quality_feedback SET quality_result=?,wrong_merge=?,duplicate_event_id=?,notes=?,review_seconds=?,reviewed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE event_id=?",r.qualityResult.name(),Boolean.TRUE.equals(r.wrongMerge),r.duplicateEventId,r.notes,r.reviewSeconds,eventId);if(n==0)jdbc.update("INSERT INTO ai_event_quality_feedback(event_id,quality_result,wrong_merge,duplicate_event_id,notes,review_seconds) VALUES(?,?,?,?,?,?)",eventId,r.qualityResult.name(),Boolean.TRUE.equals(r.wrongMerge),r.duplicateEventId,r.notes,r.reviewSeconds);}
    public Optional<EventFeedback> findFeedback(long eventId){return jdbc.query("SELECT * FROM ai_event_quality_feedback WHERE event_id=?",(x,n)->{EventFeedback f=new EventFeedback();f.eventId=x.getLong("event_id");f.qualityResult=EventQualityResult.valueOf(x.getString("quality_result"));f.wrongMerge=x.getBoolean("wrong_merge");long duplicate=x.getLong("duplicate_event_id");f.duplicateEventId=x.wasNull()?null:duplicate;f.notes=x.getString("notes");int seconds=x.getInt("review_seconds");f.reviewSeconds=x.wasNull()?null:seconds;f.reviewedAt=x.getTimestamp("reviewed_at").toLocalDateTime();return f;},eventId).stream().findFirst();}
    public void saveEval(long a,long b,MatchExpectation expected,String source,Long feedbackEventId,String notes){long first=Math.min(a,b),second=Math.max(a,b);int n=jdbc.update("UPDATE ai_event_eval_case SET expected_result=?,source_type=?,feedback_event_id=?,notes=? WHERE article_a_id=? AND article_b_id=?",expected.name(),source,feedbackEventId,notes,first,second);if(n==0)jdbc.update("INSERT INTO ai_event_eval_case(article_a_id,article_b_id,expected_result,source_type,feedback_event_id,notes) VALUES(?,?,?,?,?,?)",first,second,expected.name(),source,feedbackEventId,notes);}
    public List<EvalCase> findEvalCases(){return jdbc.query("SELECT c.*,a.title article_a_title,b.title article_b_title FROM ai_event_eval_case c JOIN ai_article a ON a.id=c.article_a_id JOIN ai_article b ON b.id=c.article_b_id ORDER BY c.created_at DESC,c.id DESC",(x,n)->{EvalCase c=new EvalCase();c.id=x.getLong("id");c.articleAId=x.getLong("article_a_id");c.articleATitle=x.getString("article_a_title");c.articleBId=x.getLong("article_b_id");c.articleBTitle=x.getString("article_b_title");c.expectedResult=MatchExpectation.valueOf(x.getString("expected_result"));c.sourceType=x.getString("source_type");long event=x.getLong("feedback_event_id");c.feedbackEventId=x.wasNull()?null:event;c.notes=x.getString("notes");c.createdAt=x.getTimestamp("created_at").toLocalDateTime();return c;});}
    public Long primaryArticle(long eventId){return jdbc.query("SELECT article_id FROM ai_event_article WHERE event_id=? ORDER BY is_primary_source DESC,id LIMIT 1",(x,n)->x.getLong(1),eventId).stream().findFirst().orElseThrow(()->new NotFoundException("Event has no article: "+eventId));}
    public Map<String,Object> dailyStats(LocalDate date){Timestamp start=Timestamp.valueOf(date.atStartOfDay()),end=Timestamp.valueOf(date.plusDays(1).atStartOfDay());Map<String,Object> raw=new LinkedHashMap<>();raw.putAll(jdbc.queryForMap("SELECT (SELECT COUNT(*) FROM ai_article WHERE created_at>=? AND created_at<?) collectedArticles,(SELECT COUNT(DISTINCT content_hash) FROM ai_article WHERE created_at>=? AND created_at<?) deduplicatedArticles,(SELECT COUNT(*) FROM ai_event WHERE created_at>=? AND created_at<?) generatedEvents,(SELECT COUNT(*) FROM ai_article a WHERE a.created_at>=? AND a.created_at<? AND EXISTS(SELECT 1 FROM ai_event_article ea WHERE ea.article_id=a.id) AND EXISTS(SELECT 1 FROM ai_event_article ea2 WHERE ea2.event_id=(SELECT ea3.event_id FROM ai_event_article ea3 WHERE ea3.article_id=a.id LIMIT 1) AND ea2.article_id<>a.id)) mergedArticles,(SELECT COUNT(*) FROM ai_article WHERE collect_status='AI_FAILED' AND updated_at>=? AND updated_at<?) aiFailed,(SELECT COUNT(*) FROM ai_event WHERE review_status='APPROVED' AND updated_at>=? AND updated_at<?) approvedEvents",start,end,start,end,start,end,start,end,start,end,start,end));raw.putAll(jdbc.queryForMap("SELECT COUNT(*) feedbackCount,SUM(CASE WHEN quality_result IN ('ACCEPT','MINOR_EDIT') THEN 1 ELSE 0 END) acceptableCount,SUM(CASE WHEN quality_result='REJECT' THEN 1 ELSE 0 END) rejectedCount,SUM(CASE WHEN wrong_merge=TRUE THEN 1 ELSE 0 END) wrongMergeCount,SUM(CASE WHEN duplicate_event_id IS NOT NULL THEN 1 ELSE 0 END) missedMergeCount,COALESCE(SUM(review_seconds),0) reviewSeconds FROM ai_event_quality_feedback WHERE reviewed_at>=? AND reviewed_at<?",start,end));raw.putAll(jdbc.queryForMap("SELECT COALESCE(SUM(input_tokens),0) inputTokens,COALESCE(SUM(output_tokens),0) outputTokens FROM ai_processing_log WHERE processed_at>=? AND processed_at<?",start,end));raw.putAll(jdbc.queryForMap("SELECT SUM(CASE WHEN page_type='HOME' THEN 1 ELSE 0 END) reportViews,SUM(CASE WHEN page_type='EVENT' THEN 1 ELSE 0 END) eventViews,SUM(CASE WHEN page_type='PRODUCT' THEN 1 ELSE 0 END) productViews FROM ai_page_view WHERE viewed_at>=? AND viewed_at<?",start,end));String[] names={"collectedArticles","deduplicatedArticles","generatedEvents","mergedArticles","aiFailed","approvedEvents","feedbackCount","acceptableCount","rejectedCount","wrongMergeCount","missedMergeCount","reviewSeconds","inputTokens","outputTokens","reportViews","eventViews","productViews"};Map<String,Object> result=new LinkedHashMap<>();for(String name:names)result.put(name,value(raw,name));return result;}
    private Object value(Map<String,Object> values,String name){for(Map.Entry<String,Object> entry:values.entrySet())if(entry.getKey().equalsIgnoreCase(name))return entry.getValue();return null;}
}
